#include "stdlib/blas/ext/base/scopy_within.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/blas/base/scopy.h"
#include "stdlib/strided/base/stride2offset.h"
#include "stdlib/math/base/special/max.h"
#include "stdlib/math/base/special/min.h"
#include <stdbool.h>
#include <stdlib.h>

/**
* Performs an in-place copy of elements within a single-precision floating-point array.
*
* @param N        number of indexed elements
* @param target   target index
* @param start    source start index
* @param end      source end index
* @param x        input array
* @param strideX  stride length
*/
void API_SUFFIX(stdlib_strided_scopy_within)( const CBLAS_INT N, const CBLAS_INT target, const CBLAS_INT start, const CBLAS_INT end, float *x, const CBLAS_INT strideX ) {
	CBLAS_INT ox = stdlib_strided_stride2offset( N, strideX );
	API_SUFFIX(stdlib_strided_scopy_within_ndarray)( N, target, start, end, x, strideX, ox );
}

/**
* Performs an in-place copy of elements within a single-precision floating-point array using alternative indexing semantics.
*
* @param N        number of indexed elements
* @param target   target index
* @param start    source start index
* @param end      source end index
* @param x        input array
* @param strideX  stride length
* @param offsetX  starting index
*/
void API_SUFFIX(stdlib_strided_scopy_within_ndarray)( const CBLAS_INT N, const CBLAS_INT target, const CBLAS_INT start, const CBLAS_INT end, float *x, const CBLAS_INT strideX, const CBLAS_INT offsetX ) {
	CBLAS_INT ssi;
	CBLAS_INT sei;
	CBLAS_INT tsi;
	CBLAS_INT tei;
	CBLAS_INT cl;
	float *tmp;
	bool flg;

	if ( N <= 0 ) {
		return;
	}
	if ( target >= N ) {
		return;
	}

	flg = false;

	// Resolve copy length:
	cl = end - start;
	if ( cl < 0 ) {
		cl = -cl;
	}
	if ( cl > N ) {
		cl = N;
	}
	if ( cl <= 0 ) {
		return;
	}

	// Calculate source and target indices:
	ssi = offsetX + ( start * strideX );
	sei = ssi + ( ( cl - 1 ) * strideX );
	tsi = offsetX + ( target * strideX );
	tei = tsi + ( ( cl - 1 ) * strideX );

	// Check if source and target regions overlap:
	if (
		!( stdlib_base_max( ssi, sei ) < stdlib_base_min( tsi, tei ) ||
		stdlib_base_max( tsi, tei ) < stdlib_base_min( ssi, sei ) )
	) {
		flg = true;
	}

	if ( flg ) {
		// Create a temporary copy of source elements:
		tmp = (float *)malloc( cl * sizeof(float) );
		if ( tmp == NULL ) {
			return;
		}
		c_scopy_ndarray( cl, x, strideX, ssi, tmp, 1, 0 );

		// Copy from temporary array to target position:
		c_scopy_ndarray( cl, tmp, 1, 0, x, strideX, tsi );

		// Clean up memory:
		free( tmp );
	} else {
		c_scopy_ndarray( cl, x, strideX, ssi, x, strideX, tsi );
	}
}
